// Characterization tests: pin the API's current behavior, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 2.5, pear: 10, gold: 60 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const json = async (res) => [res.status, res.headers.get('content-type'), await res.json()]

test('POST /orders creates an order with 201, string id, items and total', async () => {
  const items = [{ sku: 'pear', qty: 2 }]
  const [status, type, body] = await json(await post({ items }))
  assert.equal(status, 201)
  assert.equal(type, 'application/json')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, items)
  assert.equal(body.total, 20)
})

test('ids are sequential', async () => {
  const a = (await json(await post({ items: [{ sku: 'pear', qty: 1 }] })))[2]
  const b = (await json(await post({ items: [{ sku: 'pear', qty: 1 }] })))[2]
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to whole euros', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'apple', qty: 3 }] })) // 7.5
  assert.equal(body.total, 7)
})

test('total of exactly 100 gets no discount', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'pear', qty: 10 }] }))
  assert.equal(body.total, 100)
})

test('totals above 100 get 10% discount, then floored', async () => {
  let [, , body] = await json(await post({ items: [{ sku: 'gold', qty: 2 }] })) // 120 -> 108
  assert.equal(body.total, 108)
  ;[, , body] = await json(await post({ items: [{ sku: 'pear', qty: 10 }, { sku: 'apple', qty: 1 }] })) // 102.5 -> 92.25
  assert.equal(body.total, 92)
})

test('sums multiple items', async () => {
  const [, , body] = await json(await post({ items: [{ sku: 'pear', qty: 1 }, { sku: 'apple', qty: 2 }] }))
  assert.equal(body.total, 15)
})

test('POST /orders rejects missing, empty, or non-array items with 400', async () => {
  for (const payload of [{}, { items: [] }, { items: 'x' }, { items: null }]) {
    const [status, type, body] = await json(await post(payload))
    assert.equal(status, 400)
    assert.equal(type, 'application/json')
    assert.deepEqual(body, { error: 'items required' })
  }
})

test('POST /orders rejects malformed JSON with 400', async () => {
  const [status, , body] = await json(await post(null, '{nope'))
  assert.equal(status, 400)
  assert.deepEqual(body, { error: 'items required' })
})

test('POST /orders with empty body is 400', async () => {
  const res = await fetch(`${base}/orders`, { method: 'POST' })
  assert.equal(res.status, 400)
})

test('GET /orders/:id returns a created order', async () => {
  const created = (await json(await post({ items: [{ sku: 'pear', qty: 2 }] })))[2]
  const [status, type, body] = await json(await fetch(`${base}/orders/${created.id}`))
  assert.equal(status, 200)
  assert.equal(type, 'application/json')
  assert.deepEqual(body, created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const [status, , body] = await json(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(status, 200)
  assert.deepEqual(body, { error: 'not found' })
})

test('unknown routes and unsupported methods return 404 "no route"', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/extra']]) {
    const [status, type, body] = await json(await fetch(`${base}${path}`, { method }))
    assert.equal(status, 404, `${method} ${path}`)
    assert.equal(type, 'application/json')
    assert.deepEqual(body, { error: 'no route' })
  }
})
